-- 0001_init: baseline schema (idempotent, identical to the former cloudflare/schema.sql).
-- Databases bootstrapped from schema.sql can apply this safely: every statement is IF NOT EXISTS / OR IGNORE.
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, slot INTEGER NOT NULL UNIQUE CHECK(slot BETWEEN 1 AND 10), label TEXT NOT NULL, email TEXT, status TEXT NOT NULL DEFAULT 'needs_login' CHECK(status IN ('needs_login','ready','auth_required','disabled','error')), profile_ref TEXT, last_login_at TEXT, last_used_at TEXT, last_error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, aspect_ratio TEXT NOT NULL DEFAULT '9:16', status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scenes (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, scene_order INTEGER NOT NULL, prompt TEXT NOT NULL, duration_seconds INTEGER NOT NULL DEFAULT 8, status TEXT NOT NULL DEFAULT 'pending', output_key TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(project_id,scene_order));
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, scene_id TEXT REFERENCES scenes(id) ON DELETE SET NULL, account_id TEXT NOT NULL REFERENCES accounts(id), engine TEXT NOT NULL DEFAULT 'flowkit' CHECK(engine IN ('flowkit','gflow','dry-run')), status TEXT NOT NULL DEFAULT 'queued', idempotency_key TEXT NOT NULL UNIQUE, attempts INTEGER NOT NULL DEFAULT 0, error_code TEXT, error_message TEXT, result_key TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, started_at TEXT, finished_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_jobs_queue ON jobs(status,created_at);
CREATE INDEX IF NOT EXISTS idx_jobs_account ON jobs(account_id,created_at);
CREATE INDEX IF NOT EXISTS idx_scenes_project ON scenes(project_id,scene_order);
CREATE INDEX IF NOT EXISTS idx_projects_created ON projects(created_at,id);
CREATE TABLE IF NOT EXISTS worker_lease (lease_name TEXT PRIMARY KEY CHECK(lease_name='global'), holder_id TEXT NOT NULL, job_id TEXT, expires_at TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, account_id TEXT, job_id TEXT, event_type TEXT NOT NULL, detail_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_events(created_at,id);
